export type UserPermissions = {
    /**
     * 当前登录会话是否具备至少一项运行概览、日志、系统设置、备份或认证授权等运维权限。普通用户、科研用户和游客在仅有数据业务权限时为 false，前端隐藏后台入口；个人设置仍可独立访问。
     */
    canAccessAdmin: boolean;
    /**
     * 是否可配置功能权限
     */
    canManageFeaturePermissions: boolean;
    /**
     * 是否可在后台创建新用户
     */
    canCreateUser: boolean;
    /**
     * 是否可查看操作日志
     */
    canViewOperationLogs: boolean;
    /**
     * 是否可查看所有用户日志
     */
    canViewAllOperationLogs: boolean;
    /**
     * 是否可查看自己的日志
     */
    canViewOwnOperationLogs: boolean;
    /**
     * 是否可查看指定用户组日志
     */
    canViewGroupOperationLogs: boolean;
    /**
     * 是否可查看后台运行日志，由 `core.view_system_logs` 权限控制
     */
    canViewSystemLogs: boolean;
    /**
     * 是否可修改系统设置
     */
    canManageSystemSettings: boolean;
    /**
     * 是否可管理数据备份；仅内置 `超级管理员` 且具备 `core.manage_data_backup` 时为 true
     */
    canManageDataBackup: boolean;
    /**
     * 是否可修改认证授权
     */
    canManageAuth: boolean;
    /**
     * 是否可查看概览数据资源卡片
     */
    canViewDashboardResourceCard: boolean;
    /**
     * 是否可查看概览图层数卡片
     */
    canViewDashboardLayerCard: boolean;
    /**
     * 是否可查看概览栅格数量卡片
     */
    canViewDashboardRasterCard: boolean;
    /**
     * 是否可查看概览用户数量卡片
     */
    canViewDashboardUserCard: boolean;
    /**
     * 是否可查看概览活跃用户卡片
     */
    canViewDashboardActiveUsersCard: boolean;
    /**
     * 是否可查看概览系统信息
     */
    canViewDashboardSystemCard: boolean;
    /**
     * 是否可查看数据概览中的“我可见”范围、兼容旧版的全局统计字段，以及超级管理员上传用户统计；当前用户自己的上传概览无需此权限
     */
    canViewDataOverview: boolean;
    /**
     * 是否可浏览数据目录
     */
    canBrowseData: boolean;
    /**
     * 是否可查询数据
     */
    canQueryData: boolean;
    /**
     * 是否可新增数据资源，对应 `catalog.add_dataresource`
     */
    canUploadData: boolean;
    /**
     * 是否可查看存量数据资源，对应 `catalog.view_dataresource`
     */
    canViewDataResources: boolean;
    /**
     * 是否可新增数据资源，对应 `catalog.add_dataresource`
     */
    canCreateDataResources: boolean;
    /**
     * 是否可编辑数据资源，对应 `catalog.change_dataresource`
     */
    canChangeDataResources: boolean;
    /**
     * 是否可删除数据资源，对应 `catalog.delete_dataresource`
     */
    canDeleteDataResources: boolean;
    /**
     * 是否可加载矢量图层
     */
    canLoadVectorLayer: boolean;
    /**
     * 是否可加载栅格图层
     */
    canLoadRasterLayer: boolean;
    /**
     * 是否可提交自定义符号化规则
     */
    canUseCustomSymbolization: boolean;
    /**
     * 是否可使用 AI 智能解译功能，对应 `core.ai_interpretation`
     */
    canUseAiInterpretation: boolean;
    /**
     * 是否可导出数据和当前视角地图 PNG，对应 `catalog.export_dataresource`
     */
    canExportData: boolean;
    /**
     * 是否可查看工程和专题，对应 `catalog.view_workspacescene`
     */
    canViewWorkspaces: boolean;
    /**
     * 是否可新增工程和专题，对应 `catalog.add_workspacescene`
     */
    canCreateWorkspaces: boolean;
    /**
     * 是否可编辑工程和专题，对应 `catalog.change_workspacescene`
     */
    canChangeWorkspaces: boolean;
    /**
     * 是否可删除工程和专题，对应 `catalog.delete_workspacescene`
     */
    canDeleteWorkspaces: boolean;
    /**
     * 是否可查看正式出图稿，对应 `catalog.view_mapcomposition`
     */
    canViewMapCompositions: boolean;
    /**
     * 是否可从工程新建出图稿，对应 `catalog.add_mapcomposition`
     */
    canCreateMapCompositions: boolean;
    /**
     * 是否可编辑出图稿版式，对应 `catalog.change_mapcomposition`
     */
    canChangeMapCompositions: boolean;
    /**
     * 是否可永久删除出图稿，对应 `catalog.delete_mapcomposition`
     */
    canDeleteMapCompositions: boolean;
    /**
     * 是否可生成并下载 PNG、JPG 或 PDF 专题成果，对应 `catalog.export_mapcomposition`
     */
    canExportMapCompositions: boolean;
    /**
     * 是否可发布或下架专题成果，对应 `catalog.publish_mapcomposition`
     */
    canPublishMapCompositions: boolean;
    /**
     * 是否可将专题成果版本还原为新工程，对应 `catalog.restore_mapcomposition`
     */
    canRestoreMapCompositions: boolean;
    /**
     * 是否可查看访问范围内的成果文件，对应 `catalog.view_resultartifact`
     */
    canViewResultArtifacts: boolean;
    /**
     * 是否可导入成果文件，对应 `catalog.add_resultartifact`；实际导入还需成果查看和发布权限
     */
    canImportResultArtifacts: boolean;
    /**
     * 是否可下载成果原文件，对应 `catalog.download_resultartifact`
     */
    canDownloadResultArtifacts: boolean;
    /**
     * 是否可直接发布、更新发布范围或下架成果文件，对应 `catalog.publish_resultartifact`
     */
    canPublishResultArtifacts: boolean;
    /**
     * 是否可删除本人或管理范围内的成果文件，对应 `catalog.delete_resultartifact`
     */
    canDeleteResultArtifacts: boolean;
    /**
     * 是否可管理栅格数据集
     */
    canManageRasterData: boolean;
};

export type AdminPermissionItem = {
    /**
     * 权限完整标识，格式为 app_label.codename
     */
    id: string;
    /**
     * 权限中文名称
     */
    label: string;
    /**
     * 权限在管理界面中的分组名称，当前按后台权限、数据权限、人员权限归类
     */
    group: string;
};

export type AdminProfileResponse = {
    user: UserInfo;
    /**
     * 当前用户头像 URL
     */
    avatarUrl: string;
    /**
     * 当前用户部门
     */
    department: string;
    /**
     * 上级授予当前用户的功能权限列表
     */
    grantedPermissions: Array<string>;
    /**
     * 当前用户主动关闭的已授予权限列表
     */
    disabledPermissions: Array<string>;
    /**
     * 授予权限扣除主动关闭权限后的实际生效权限列表
     */
    effectivePermissions: Array<string>;
    /**
     * 管理后台可展示的功能权限元数据
     */
    availablePermissions: Array<AdminPermissionItem>;
};

export type AdminProfileUpdateRequest = {
    /**
     * 新用户名
     */
    username?: string;
    /**
     * 新展示名称
     */
    displayName?: string;
    /**
     * 新邮箱；提交时不能为空，后端统一转为小写并保证非空邮箱唯一
     */
    email?: string;
    /**
     * 新头像 URL
     */
    avatarUrl?: string;
    /**
     * 新部门
     */
    department?: string;
};

export type AdminProfilePermissionsRequest = {
    /**
     * 用户主动关闭的权限列表，必须全部属于 grantedPermissions
     */
    disabledPermissions: Array<string>;
};

export type AdminProfilePasswordRequest = {
    /**
     * 当前登录密码
     */
    currentPassword: string;
    /**
     * 新密码，至少 6 位
     */
    newPassword: string;
    /**
     * 新密码确认值，必须与 newPassword 一致
     */
    passwordConfirm: string;
};

export type AdminOperationLog = {
    /**
     * 操作日志 ID
     */
    id: number;
    /**
     * 本地时区格式化后的操作时间
     */
    occurredAt: string;
    /**
     * 操作用户显示名称，系统操作显示为“系统”
     */
    operator: string;
    /**
     * 操作所属模块
     */
    module: string;
    /**
     * 操作动作
     */
    action: string;
    /**
     * 操作结果
     */
    result: 'success' | 'warning' | 'failed';
    /**
     * 结构化操作目标类型；数据资源为 data_resource，工程/专题为 workspace_scene；无明确单一目标时为空字符串
     */
    targetType: string;
    /**
     * 操作目标的后台数据库 ID；删除后仍保留删除前 ID，无明确单一目标时为 null
     */
    targetId: number | null;
    /**
     * 操作目标编码；数据资源为 code，工程/专题为 kind，无编码时为空字符串
     */
    targetCode: string;
    /**
     * 操作目标名称；删除后仍保留删除前名称，无明确单一目标时为空字符串
     */
    targetName: string;
    /**
     * 客户端 IP 地址，为空字符串表示未记录
     */
    ipAddress: string;
    /**
     * 操作摘要
     */
    summary: string;
};

export type AdminOperationLogListResponse = {
    /**
     * 当前页操作日志
     */
    items: Array<AdminOperationLog>;
    /**
     * 符合筛选条件的总记录数
     */
    total: number;
};

export type AdminSystemLogFile = {
    /**
     * 日志文件名，不包含服务器绝对路径
     */
    name: string;
    /**
     * 日志文件大小，单位字节
     */
    sizeBytes: number;
    /**
     * 日志文件最近修改时间
     */
    modifiedAt: string;
};

export type AdminSystemLogResponse = {
    /**
     * 可选择的后台日志文件列表，按最近修改时间倒序排列
     */
    files: Array<AdminSystemLogFile>;
    /**
     * 当前读取的日志文件名；当没有日志文件时为空字符串
     */
    selectedFile: string;
    /**
     * 本次返回的尾部日志行数上限
     */
    lines: number;
    /**
     * 当前日志文件尾部文本内容，按 UTF-8 解码，无法解码的字符会被替换
     */
    content: string;
    /**
     * 本次日志读取时间
     */
    generatedAt: string;
};

export type AdminDashboardResponse = {
    /**
     * 概览统计生成时间
     */
    generatedAt: string;
    cards: AdminDashboardCards;
};

/**
 * 按当前用户卡片权限返回的概览卡片数据；未授权卡片字段会被省略。dataOverview 始终包含当前用户自己的上传概览，其他范围由权限控制。
 */
export type AdminDashboardCards = {
    resources?: AdminDashboardResourceCard;
    layers?: AdminDashboardLayerCard;
    rasters?: AdminDashboardRasterCard;
    dataOverview?: AdminDashboardDataOverviewCard;
    users?: AdminDashboardUserCard;
    activeUsers?: AdminDashboardActiveUsers;
};

export type AdminDashboardResourceCard = {
    /**
     * 数据资源总数
     */
    total: number;
    /**
     * 启用状态的数据资源数量
     */
    active: number;
};

export type AdminDashboardLayerCard = {
    /**
     * 图层总数
     */
    total: number;
    /**
     * 启用状态的图层数量
     */
    active: number;
};

export type AdminDashboardRasterCard = {
    /**
     * 栅格数据资源数量
     */
    resources: number;
    /**
     * 栅格数据集数量
     */
    datasets: number;
    /**
     * 栅格图层数量
     */
    layers: number;
};

export type AdminDashboardDataOverviewCard = {
    /**
     * 系统数据资源总数，用于兼容旧版概览卡片；仅具备 `core.view_data_overview` 权限时返回，新版界面优先展示分组统计
     */
    totalResources?: number;
    /**
     * 系统启用状态数据资源数量，用于兼容旧版概览卡片；仅具备 `core.view_data_overview` 权限时返回，新版界面优先展示分组统计
     */
    activeResources?: number;
    /**
     * 系统数据总大小，单位字节，用于兼容旧版概览卡片；仅具备 `core.view_data_overview` 权限时返回，新版界面优先展示分组统计
     */
    totalSizeBytes?: number;
    /**
     * 系统数据条目总数，用于兼容旧版概览卡片；仅具备 `core.view_data_overview` 权限时返回，新版界面优先展示分组统计
     */
    totalItemCount?: number;
    /**
     * 系统按数据类型聚合的数据情况，用于兼容旧版概览卡片；仅具备 `core.view_data_overview` 权限时返回，新版界面优先展示分组统计
     */
    typeBreakdown?: Array<AdminDashboardDataTypeOverview>;
    /**
     * 当前用户上传的数据资源聚合统计；登录用户无需额外功能权限即可查看
     */
    ownUploads: AdminDashboardDataOverviewScope;
    /**
     * 当前用户可见的数据资源聚合统计；仅具备 `core.view_data_overview` 权限时返回，后端按数据可见范围和上传者本人规则裁剪
     */
    visibleResources?: AdminDashboardDataOverviewScope;
    /**
     * 具备 `core.view_data_overview` 权限的超级管理员主体可见的上传用户统计；普通用户无该字段
     */
    uploaders?: Array<AdminDashboardUploaderOverview>;
};

export type AdminDashboardDataOverviewScope = {
    /**
     * 该统计范围内的数据资源总数
     */
    totalResources: number;
    /**
     * 该统计范围内启用状态的数据资源数量
     */
    activeResources: number;
    /**
     * 该统计范围内数据总大小，单位字节
     */
    totalSizeBytes: number;
    /**
     * 该统计范围内数据条目总数
     */
    totalItemCount: number;
    /**
     * 该统计范围内按数据类型聚合的数据情况；始终返回平台支持的全部物理类型，暂无资源的类型计数为 0
     */
    typeBreakdown: Array<AdminDashboardDataTypeOverview>;
    /**
     * 该统计范围内按当前权威业务分类体系聚合的数据情况；始终返回全部启用的大类和小类，暂无资源的分类计数为 0
     */
    categoryBreakdown: Array<AdminDashboardCategoryOverview>;
    /**
     * 该统计范围内尚未挂接权威业务分类的数据资源数量
     */
    unclassifiedCount: number;
    /**
     * 该统计范围内可用于数据概览空间可视化的权限裁剪后空间摘要；仅基于当前分组内用户有权查看的数据资源计算
     */
    spatialSummary: AdminDashboardSpatialSummary;
};

export type AdminDashboardDataTypeOverview = {
    /**
     * 数据类型
     */
    dataType: 'vector' | 'raster' | 'gene' | 'table' | 'document' | 'image';
    /**
     * 该类型数据资源数量
     */
    count: number;
    /**
     * 该类型数据大小，单位字节
     */
    sizeBytes: number;
    /**
     * 该类型数据条目数
     */
    itemCount: number;
};

export type AdminDashboardCategoryOverview = {
    /**
     * 一级业务分类编码
     */
    categoryCode: string;
    /**
     * 一级业务分类名称
     */
    categoryName: string;
    /**
     * 该大类及其全部小类的数据资源数量
     */
    count: number;
    /**
     * 该大类及其全部小类的数据大小，单位字节
     */
    sizeBytes: number;
    /**
     * 该大类及其全部小类的数据条目数
     */
    itemCount: number;
    /**
     * 当前大类下全部启用的小类统计，按分类排序返回并包含零计数项
     */
    children: Array<AdminDashboardCategoryLeafOverview>;
};

export type AdminDashboardCategoryLeafOverview = {
    /**
     * 二级业务分类编码
     */
    categoryCode: string;
    /**
     * 二级业务分类名称
     */
    categoryName: string;
    /**
     * 该小类的数据资源数量
     */
    count: number;
    /**
     * 该小类的数据大小，单位字节
     */
    sizeBytes: number;
    /**
     * 该小类的数据条目数
     */
    itemCount: number;
};

export type AdminDashboardSpatialSummary = {
    /**
     * 当前统计范围内具备有效经纬度 bbox 的空间数据资源数量
     */
    spatialResourceCount: number;
    /**
     * 当前统计范围内暂无可解析经纬度空间范围的数据资源数量
     */
    missingSpatialResourceCount: number;
    /**
     * 当前统计范围内所有有效空间范围合并后的经纬度 bbox，顺序为 `[minLng, minLat, maxLng, maxLat]`；没有空间范围时为空数组
     */
    totalBounds: Array<number>;
    /**
     * 当前统计范围内用于绘制空间覆盖框的数据资源摘要，后端最多返回 80 项并按覆盖面积优先；所有条目均已按当前用户权限裁剪
     */
    resourceExtents: Array<AdminDashboardResourceExtent>;
    /**
     * `resourceExtents` 是否因数量超过前端概览展示上限而被截断
     */
    resourceExtentsTruncated: boolean;
    /**
     * 当前统计范围内空间覆盖面积最大的前 10 个数据资源；所有条目均已按当前用户权限裁剪
     */
    coverageRanking: Array<AdminDashboardResourceExtent>;
    /**
     * 当前统计范围内按资源中心点聚合的热力网格；仅基于当前用户有权查看的数据资源生成，不包含未授权资源
     */
    heatmapCells: Array<AdminDashboardSpatialHeatmapCell>;
};

export type AdminDashboardResourceExtent = {
    /**
     * 数据资源 ID
     */
    resourceId: number;
    /**
     * 数据资源名称
     */
    name: string;
    /**
     * 数据类型
     */
    dataType: 'vector' | 'raster' | 'gene' | 'table' | 'document' | 'image';
    /**
     * 数据资源经纬度 bbox，顺序为 `[minLng, minLat, maxLng, maxLat]`
     */
    bounds: [
        number,
        number,
        number,
        number
    ];
    /**
     * 数据资源 bbox 中心点，顺序为 `[lng, lat]`
     */
    center: [
        number,
        number
    ];
    /**
     * 根据经纬度 bbox 估算的覆盖面积，单位平方公里，用于概览排行和相对比较
     */
    coverageAreaKm2: number;
    /**
     * 数据大小，单位字节
     */
    sizeBytes: number;
    /**
     * 数据条目数
     */
    itemCount: number;
    /**
     * 数据坐标系说明；未知时为空字符串
     */
    coordinateSystem: string;
    /**
     * 上传者或维护者展示名；未记录时返回“未记录”
     */
    uploaderName: string;
    /**
     * 数据资源最近更新时间
     */
    updatedAt: string;
};

export type AdminDashboardSpatialHeatmapCell = {
    /**
     * 热力网格列序号，从 0 开始
     */
    column: number;
    /**
     * 热力网格行序号，从 0 开始
     */
    row: number;
    /**
     * 热力网格经纬度 bbox，顺序为 `[minLng, minLat, maxLng, maxLat]`
     */
    bounds: [
        number,
        number,
        number,
        number
    ];
    /**
     * 落入该网格的数据资源数量
     */
    resourceCount: number;
    /**
     * 落入该网格的数据资源条目数合计
     */
    itemCount: number;
};

export type AdminDashboardUploaderOverview = {
    user: UserReference;
    /**
     * 该用户上传或维护的数据资源数量
     */
    resourceCount: number;
    /**
     * 该用户数据大小，单位字节
     */
    sizeBytes: number;
    /**
     * 该用户数据条目数
     */
    itemCount: number;
};

export type AdminDashboardUserCard = {
    /**
     * 系统用户总数
     */
    total: number;
    /**
     * 启用账号数量
     */
    active: number;
    /**
     * 停用账号数量
     */
    disabled: number;
    /**
     * 用户组数量
     */
    groups: number;
    /**
     * 矢量数据资源数量
     */
    vectorResources: number;
    /**
     * 表格数据资源数量
     */
    tableResources: number;
};

